"""Private standalone visual review. Lossless atlas crops only; no art/portal build."""
from pathlib import Path
from PIL import Image
import json,hashlib,datetime,io,base64,html,gzip
R=Path.cwd();D=R/'docs/review-final';S=Path('/workspace/review-pages-compiled');P=Path('/workspace/review-pages-destination');D.mkdir(exist_ok=True)
sha=lambda b:hashlib.sha256(b).hexdigest()
rights=json.loads((R/'assets-src/rights/npc-inventory.json').read_text())['assets'];catalog=json.loads((S/'catalog.json').read_text())['npcs'];names={n['id']:n for n in catalog};assert len(names)==26
manifest=json.loads((S/'export-manifest.json').read_text());manifest_hash=sha((S/'export-manifest.json').read_bytes());assert manifest_hash=='40c129fb774adf14e2bd9f707d2c50e5fe24d89d438d654172ed02e33b73018d'
for row in manifest['files']:assert sha((S/row['filename']).read_bytes())==row['sha256']
policy=json.loads((P/'review-candidates/phase3b-a.json').read_text());assert policy['decision']=='PENDING'and policy['manifestSHA256']==manifest_hash
notes={
'npc-history-seondeok':('Trang sức phân nhánh / dáng lễ phục gợi thời Silla. Chưa có nguồn tranh hoặc thiết kế phục trang cụ thể được xác lập là bản sao; so sánh chuyên biệt vẫn còn mở.','Chỉ khi có nguồn cụ thể bị vướng: tạo trang sức nguyên bản độc lập trong vùng trang sức; giữ mặt, phần thân và đăng ký khung động. Không tự sửa bản đã duyệt.'),
'npc-history-sejong':('Áo đỏ, họa tiết trung tâm và mũ đen tạo liên tưởng mạnh đến hình tượng hoàng gia Joseon. Chưa thực hiện so sánh đầy đủ với chân dung chuẩn hóa hiện đại.','Nếu xác lập trùng một nguồn cụ thể: thay đúng họa tiết hoặc viền mũ bị vướng bằng thiết kế nguyên bản; không chỉ đổi tên/màu, không sửa toàn bộ nhân vật.'),
'npc-history-jang':('Trang phục thợ và dụng cụ khoa học: chưa ghi nhận ảnh bảo tàng đầu vào; thiết kế dụng cụ và điều khoản tạo art chưa được xác minh độc lập.','Nếu dụng cụ trùng một thiết kế cụ thể: vẽ dụng cụ hư cấu độc lập trong đúng vùng prop và những frame có prop; giữ rig, tay neo và dáng nhân vật.'),
'npc-history-saimdang':('Dáng họa sĩ và phục trang có thể gợi ngữ cảnh chân dung chuẩn hóa; không có tranh/ảnh tiền giấy được ghi nhận là đầu vào. Chưa có kết luận sao chép cụ thể.','Nếu phát hiện chi tiết trùng nguồn xác định: thiết kế lại duy nhất phụ kiện hoặc chi tiết trang phục bị vướng, giữ bản gốc và xin duyệt candidate riêng.'),
'npc-history-yi':('Mũ/giáp chỉ huy hàng hải có thể gợi trang phục phim hoặc chân dung chưa được đối chiếu. Không có ảnh diễn viên/phim được ghi nhận là đầu vào.','Nếu có đối chiếu cụ thể: tạo huy hiệu hoặc phần viền mũ/giáp độc lập thay cho chi tiết bị vướng, không vẽ lại cả người hoặc thay atlas mặc định.'),
'npc-history-yu':('Dáng học sinh đầu thế kỷ XX có thể gợi ảnh lịch sử. Không ghi nhận ảnh thật làm đầu vào; liên tưởng ngữ cảnh không phải kết luận sao chép.','Nếu nhận diện được chi tiết sao chép từ một ảnh cụ thể: chỉ tạo lại vùng nhận diện bị vướng trong candidate nguyên bản, giữ các phần không bị ảnh hưởng và bộ chuyển động đã duyệt.')}
rows=[];cards=[];hero=[]
def esc(s):return html.escape(str(s),quote=True)
def png(im):
 o=io.BytesIO();im.save(o,format='PNG',optimize=True);assert Image.open(io.BytesIO(o.getvalue())).tobytes()==im.tobytes();return'data:image/png;base64,'+base64.b64encode(o.getvalue()).decode()
for a in rights:
 id=a['stableId'];n=names[id];checks=[]
 for evidence in a['sourceEvidence']:
  path=R/evidence['path'];got=sha(path.read_bytes())if path.is_file()else None;checks.append({'path':evidence['path'],'expectedSHA256':evidence['sha256'],'actualSHA256':got,'matches':got==evidence['sha256']})
 assert all(c['matches']for c in checks),(id,checks)
 atlas_path=R/a['primaryAssets']['texture'];atlas_hash=sha(atlas_path.read_bytes());assert atlas_hash==a['afterAtlasSHA256']==a['beforeAtlasSHA256'];runtime=S/'play'/str(Path(a['primaryAssets']['texture']).relative_to('public'));assert sha(runtime.read_bytes())==atlas_hash
 frames=json.loads((R/a['primaryAssets']['atlas']).read_text())['frames'];image=Image.open(atlas_path).convert('RGBA');views=[]
 for direction,label in [('front','Trước'),('back','Sau'),('left','Trái'),('right','Phải')]:
  f=frames['idle-'+direction+'-0']['frame'];crop=image.crop((f['x'],f['y'],f['x']+f['w'],f['y']+f['h']));assert crop.size==(96,112);views.append(f'<figure><img width="96" height="112" src="{png(crop)}" alt="{esc(n["name"]["vi"])} · {label}"><figcaption>{label} · 1:1</figcaption></figure>')
 archive=n['archive'];
 if archive:hero.append(f'<a href="#{esc(id)}"><img data-hero-id="{esc(id)}" width="96" height="112" alt="{esc(n["name"]["vi"])}"><span>{esc(n["name"]["vi"])}</span></a>')
 concern,proposal=notes.get(id,('Hồ sơ đầu vào mô tả người hư cấu; chưa xác lập ảnh người nổi tiếng, logo hoặc tác phẩm cụ thể bị sao chép trong phạm vi kiểm tra này. Đây không phải tìm kiếm ngược toàn diện hay cấp phép.','Không có lý do cụ thể để đề nghị vẽ lại. Nếu có nguồn đối chiếu thực tế, khoanh đúng vùng bị vướng và xin duyệt candidate độc lập; không sửa ngầm.'))
 strip=''
 if archive:
  film=Image.new('RGBA',(96*4,112))
  for k,key in enumerate(['activity-front-0','activity-back-0','activity-right-4','greet-front-4']):
   f=frames[key]['frame'];film.paste(image.crop((f['x'],f['y'],f['x']+96,f['y']+112)),(96*k,0))
  strip=f'<details><summary>Động tác / đạo cụ gốc (không phải gameplay)</summary><div class="film"><img src="{png(film)}" width="384" height="112" alt="Activity trước / sau / phải và greet gốc"></div></details>'
 row={'id':id,'name':n['name'],'archive':archive,'role':n['role'],'risk':a['risk'],'atlasSHA256':atlas_hash,'sourceEvidence':checks,'creatorTool':a['creatorTool'],'referenceChain':a['referenceChain'],'explicitLicenseEvidence':a['explicitLicenseEvidence'],'provenanceIntegrity':'PASS exact hashes','permission':'UNKNOWN / commercial BLOCKED_PENDING_REVIEW','concern':concern,'conditionalRedesignProposal':proposal,'concreteCopiedThirdPartyWorkIdentified':False,'artChangePerformed':False};rows.append(row)
 cards.append(f'''<article id="{esc(id)}" data-id="{esc(id)}" class="card {'archive'if archive else''}"><h3>{esc(n['name']['vi'])} · {esc(n['name']['ko'])}</h3><p>{esc(n['role'])} · {esc(n['zone'])}<br><small>{esc(id)}</small></p><span class="pill">{esc(a['risk'])} · public PENDING</span><div class="views">{''.join(views)}</div>{strip}<p><strong>Đánh giá hiện có:</strong> {esc(concern)}</p><details><summary>Provenance và giới hạn quyền</summary><p>Chuỗi nguồn → rig → atlas: {len(checks)} tệp khớp SHA256. Atlas gốc và bản runtime trùng byte. Việc này không chứng minh quyền.</p><p>Công cụ ghi trong hồ sơ: {esc(a['creatorTool']['recordedRoute'])}. Model/tài khoản/điều khoản khi tạo: UNKNOWN. Không suy luận giấy phép thương mại từ MIT hay tên hư cấu.</p><p class="hash">Atlas SHA256: {atlas_hash}</p></details><details><summary>Phương án tối thiểu nếu xác lập vấn đề cụ thể</summary><p>{esc(proposal)}</p><p>Đây chỉ là phương án có điều kiện, không phải kết luận cần vẽ lại. Không tạo hoặc áp dụng art mới trong lượt này.</p></details><fieldset><legend>Quyết định của chủ dự án cho mục này</legend><label>Phạm vi public preview <select data-field="decision"><option value="PENDING">PENDING — chưa quyết định</option><option value="ALLOW_PUBLIC_PREVIEW">Cho phép public preview</option><option value="HOLD">HOLD — cần xử lý riêng</option></select></label><label><input type="checkbox" data-field="reviewed"> Tôi đã xem hình/hồ sơ mục này; không còn vấn đề sao chép cụ thể chưa xử lý trong quyết định preview của tôi.</label><label>Nhận xét riêng {'(bắt buộc với 6 mục theo thời kỳ khi cho phép)'if archive else'(có thể dùng lý do chung)'}<textarea data-field="note" rows="2"></textarea></label></fieldset></article>''')
report={'checkedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'npcCount':26,'sourceEvidenceChecks':sum(len(r['sourceEvidence'])for r in rows),'sourceHashMatches':True,'all26ApprovedRuntimeAtlasesUnchanged':True,'providerAccountTerms':'UNKNOWN','commercialRelease':'BLOCKED_PENDING_REVIEW','publicPreviewDecision':'PENDING','newGenerationCalls':0,'artChanges':0,'concreteThirdPartyCopyEstablished':False,'scope':'Actual recorded source-file hashes and existing concern review only; no new reverse-image search, legal opinion or license inferred','rows':rows}
(D/'PROVENANCE_AUDIT.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
(D/'PUBLIC_PREVIEW_APPROVAL.pending.json').write_text(json.dumps(policy,ensure_ascii=False,indent=2)+'\n')
# Full exact served-file manifest is unchanged and available to the owner on this one page.
data={'audit':[{'id':r['id'],'archive':r['archive'],'concern':r['concern']}for r in rows],'provenanceGzip':base64.b64encode(gzip.compress(json.dumps(report,ensure_ascii=False,indent=2).encode(),mtime=0)).decode(),'manifestGzip':base64.b64encode(gzip.compress((S/'export-manifest.json').read_bytes(),mtime=0)).decode(),'template':policy,'manifestSHA256':manifest_hash,'assetCount':len(manifest['files'])};encoded=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
html_text='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><link rel="icon" href="data:,"><title>Duyệt public preview — 26 NPC Korean Pixel Town</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#10212b;color:#edf5ef;font:16px/1.6 system-ui,sans-serif}header,main,footer{max-width:1250px;margin:auto;padding:24px}h1,h2,h3{color:#ffd28c}h1{font-size:clamp(1.6rem,4vw,2.7rem)}a{color:#ffe0a8}.hero{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0}.hero a{width:112px;text-align:center;text-decoration:none;font-size:14px}.hero img{display:block;margin:auto;image-rendering:pixelated}.hero span{display:block}nav{display:flex;gap:12px;flex-wrap:wrap}.notice{padding:16px;border:2px solid #dfaa6e;background:#2d2927}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,530px),1fr));gap:20px}.card,section{padding:20px;background:#19313c;border:1px solid #46616b;margin-bottom:20px}.archive{border-top:4px solid #e6b268}.views{display:flex;flex-wrap:wrap;gap:14px;margin:12px 0}.views figure{margin:0;text-align:center}.views img{display:block;image-rendering:pixelated;background:#102630}.zoom .views img{width:192px;height:224px}.film{overflow:auto}.film img{image-rendering:pixelated;max-width:none}.pill{font-size:.82rem;padding:6px;background:#423629;color:#ffe2ac}.hash{overflow-wrap:anywhere;font:12px monospace}label{display:block;margin:10px 0}input:not([type=checkbox]),textarea,select,button{font:inherit;min-height:44px;padding:10px;border:1px solid #6a848e;background:#10232e;color:#fff;width:100%}input[type=checkbox]{width:22px;height:22px;vertical-align:middle}button{cursor:pointer;background:#36535d;margin:8px 0}button.primary{background:#d8b279;color:#12212b}button:disabled{opacity:.55;cursor:not-allowed}fieldset{border:1px solid #46616b}summary{min-height:44px;padding:10px;cursor:pointer}small{color:#b8cdd5}pre{white-space:pre-wrap;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #46616b;text-align:left;padding:9px}details{margin:8px 0}.ready{color:#9fe1b2}.blocked{color:#ffcf95}.skip{position:absolute;left:-9999px}.skip:focus{left:8px;top:8px;background:#000;padding:10px}*:focus-visible{outline:3px solid #8ae5df;outline-offset:3px}@media(max-width:600px){header,main,footer{padding:14px}.card,section{padding:14px}}
</style></head><body><a class="skip" href="#review">Đến nội dung</a><header><p>KOREAN PIXEL TOWN · HỒ SƠ DUYỆT CỤC BỘ</p><h1>Một trang duyệt hình ảnh & quyền · 26 NPC</h1><p class="notice"><strong>PUBLIC EXPOSURE: PENDING · GAME CHƯA ĐƯỢC XUẤT BẢN.</strong><br>Trang này chứa artwork chưa được cho phép công khai: chỉ mở cục bộ, không đăng lên repo/site public. Noindex không phải mật khẩu. Đây không phải cấp phép pháp lý hoặc duyệt thương mại.</p><p>14 cư dân + 6 khách hư cấu + 6 nhân vật hư cấu theo cảm hứng thời kỳ. Đây là crop lossless từ atlas đã duyệt, không phải art mới hay game dựng lại. Các danh tính không phải người lịch sử thật.</p><nav><a href="#era">6 mục cần xem kỹ</a><a href="#others">20 mục còn lại</a><a href="#assets">Manifest chính xác</a><a href="#decision">Quyết định tổng hợp</a></nav></header><header class="hero">'''+''.join(hero)+'''</header><header><details><summary>Manifest chính xác / checkpoint / phạm vi gói</summary><p>Manifest SHA256: <span class="hash">'''+manifest_hash+'''</span><br>Source checkpoint: 0e4b5016 · portal f4576307 · compiled candidate ee0a928<br>1367 tệp được phục vụ, 26 atlas giữ nguyên byte. Chỉ có một quyết định tổng hợp; không cần các lượt micro-approval tách rời.</p></details><label><input id="zoom" type="checkbox"> Xem lớn bằng nearest-neighbor (không đổi ảnh gốc)</label></header><main id="review"><section><details><summary>Cấu hình triển khai đã xác minh</summary><p>Pages: GitHub Actions, HTTPS bật. Workflow triển khai active. Environment yêu cầu 1 người duyệt và chỉ cho nhánh main. Lượt kiểm tra cấu hình không xuất bản: 40858140452.</p><p><strong>Endpoint game hiện HTTP 404 — chưa có game live.</strong> Chỉ còn gate duyệt public exposure và các quyền asset chưa được xác minh; không cần rebuild portal. Một số cấu hình quản trị Actions trả 403 / administration=read, không đồng nghĩa workflow bị tắt.</p></details></section><section><details><summary>Điều gì đã kiểm chứng — và chưa chứng minh?</summary><p><strong>PASS kỹ thuật:</strong> hash tệp nguồn/master/turnaround/rig/atlas trùng hồ sơ; 26 atlas runtime trùng byte với bản đã duyệt.</p><p><strong>Chưa chứng minh:</strong> model/tài khoản/điều khoản lúc tạo, quyền likeness và giấy phép sử dụng thương mại. Không ghi nhận nguồn bên thứ ba cụ thể đã được xác lập là bản sao trong phạm vi hồ sơ hiện có; đây không phải rà soát tương đồng toàn diện. Sáu liên tưởng cần xem kỹ bên dưới vẫn còn mở.</p><p>Nếu nêu được một nguồn đối chiếu cụ thể, chỉ đề xuất vùng cần thiết kế nguyên bản độc lập để duyệt riêng. Không đổi art chỉ vì tên thời kỳ hoặc nghề nghiệp, không coi đổi tên/màu là giải pháp quyền.</p></details></section><h2 id="era">6 nhân vật theo cảm hứng thời kỳ — cần quyết định riêng trong cùng hồ sơ</h2><div class="grid">'''+''.join(c for r,c in zip(rows,cards)if r['archive'])+'''</div><h2 id="others">20 nhân vật hư cấu còn lại</h2><div class="grid">'''+''.join(c for r,c in zip(rows,cards)if not r['archive'])+'''</div><section id="assets"><h2>Toàn bộ asset sẽ được public</h2><p>Manifest dưới đây bao gồm game đã biên dịch, ảnh/atlas, video, metadata, runtime world, nhân vật người chơi và cosmetics. Chỉ duyệt NPC không đủ để cho phép cả gói. Không kèm source master, prompt thô, token hay hồ sơ học viên.</p><details><summary>1367 đường dẫn / hash / origin / trạng thái</summary><input id="filter" aria-label="Lọc đường dẫn manifest" placeholder="Lọc NPC, atlas, video…"><pre id="manifest-list"></pre></details><button id="download-manifest">Tải manifest gốc chính xác</button><button id="download-provenance">Tải báo cáo 309 đối chiếu nguồn / hash</button></section><section id="decision"><h2>Một quyết định tổng hợp</h2><p>Form không gửi dữ liệu lên mạng và không tự publish. Chỉ xuất JSON để chủ dự án kiểm tra lại. Cho phép public preview khác với quyền phát hành thương mại; trạng thái thương mại luôn BLOCKED_PENDING_REVIEW.</p><label>Tên/tài khoản người duyệt<input id="owner" autocomplete="off"></label><label>Thời điểm chủ dự án đưa ra quyết định<input id="when" type="datetime-local"></label><label>Lý do/phạm vi exposure chung<textarea id="reason" rows="3" placeholder="Ghi rõ phạm vi public preview và các giới hạn/điều khoản chưa xác minh…"></textarea></label><h3>Các nhóm asset khác trong gói</h3><div id="groups"></div><label><input id="ack" type="checkbox"> Tôi hiểu: tên hư cấu, hash, MIT, noindex và kiểm thử không tạo quyền; tôi đang quyết định public exposure của đúng gói này, không cấp phép thương mại hoặc cho phép Phase 3B-B.</label><p id="summary" role="status"></p><button id="pending">Tải hồ sơ PENDING / các mục HOLD</button><button id="approve" class="primary" disabled>Xuất quyết định PUBLIC PREVIEW đã hoàn tất</button><p>Nếu còn HOLD/PENDING, không push game/art và không chạy deploy. Candidate cần sửa phải giữ bản chuẩn, có manifest mới và được duyệt riêng. Trang này không giả lập phán quyết pháp lý.</p></section></main><footer>Game và portal không được rebuild. Original artwork/checkpoint/v0.5 giữ nguyên. Phase 3B-B/C/D LOCKED · Thiết bị thật/GPU NOT TESTED.</footer><script id="review-data" type="application/json">'''+encoded+r'''</script><script>
async function start(){
const data=JSON.parse(document.getElementById('review-data').textContent);
const zipped=Uint8Array.from(atob(data.manifestGzip),c=>c.charCodeAt(0));
const manifestBytes=new Uint8Array(await new Response(new Blob([zipped]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());
data.manifest=JSON.parse(new TextDecoder().decode(manifestBytes));
for(const image of document.querySelectorAll('[data-hero-id]'))image.src=document.getElementById(image.dataset.heroId).querySelector('.views img').src;
const groupNames={'world':'Thế giới / kiến trúc / signage','playable-characters':'12 nhân vật người chơi','cosmetics':'28 cosmetics','third-party-code-fonts-audio':'Code / font / audio và notices','checkpoint-media':'Video checkpoint / ảnh cùng nội dung','portal-and-metadata':'Portal / metadata / provenance công khai'};
for(const [id,title]of Object.entries(groupNames)){const label=document.createElement('label');const check=document.createElement('input');check.type='checkbox';check.dataset.group=id;label.append(check,document.createTextNode(' '+title+' — cho phép preview sau khi kiểm tra phạm vi/nguồn'));document.getElementById('groups').append(label)}
document.getElementById('zoom').onchange=e=>document.body.classList.toggle('zoom',e.target.checked);
function refreshManifest(){const filter=document.getElementById('filter').value.toLowerCase();document.getElementById('manifest-list').textContent=data.manifest.files.filter(r=>r.filename.toLowerCase().includes(filter)).map(r=>r.filename+'\n SHA256 '+r.sha256+'\n Origin: '+r.origin+'\n Public: '+r.publicPreviewDecision+' · Commercial: '+r.commercialRelease).join('\n\n')}
refreshManifest();document.getElementById('filter').oninput=refreshManifest;
function make(){const p=structuredClone(data.template);let allowed=0;for(const a of data.audit){const card=document.getElementById(a.id),decision=card.querySelector('[data-field=decision]').value,checked=card.querySelector('[data-field=reviewed]').checked,note=card.querySelector('[data-field=note]').value.trim();const r=p.npcReviews[a.id];r.decision=decision;r.unresolvedSpecificConcern=decision==='HOLD'?true:checked?false:null;r.depictionReview=checked?(a.concern+' | Chủ dự án đã xác nhận xem hồ sơ. '+note):'';r.exposureJustification=note||document.getElementById('reason').value.trim();if(decision==='ALLOW_PUBLIC_PREVIEW'&&checked&&r.exposureJustification&&(!a.archive||note))allowed++}for(const [id]of Object.entries(groupNames)){const checked=document.querySelector('[data-group="'+id+'"]').checked;p.groups[id]={decision:checked?'ALLOW_PUBLIC_PREVIEW':'PENDING',justification:checked?document.getElementById('reason').value.trim():''}}p.approvedBy=document.getElementById('owner').value.trim();const when=document.getElementById('when').value;p.approvedAt=when?new Date(when).toISOString():'';const done=allowed===26&&p.approvedBy&&p.approvedAt&&document.getElementById('reason').value.trim()&&Object.values(p.groups).every(g=>g.decision==='ALLOW_PUBLIC_PREVIEW'&&g.justification)&&document.getElementById('ack').checked;p.decision=done?'APPROVED_PUBLIC_PREVIEW':'PENDING';return{p,done,allowed}}
function refresh(){const s=make();document.getElementById('approve').disabled=!s.done;document.getElementById('summary').textContent=s.allowed+'/26 mục đủ điều kiện trong quyết định của bạn. '+(s.done?'Đủ dữ liệu để xuất; chưa publish và không phải cấp phép pháp lý.':'Vẫn PENDING/HOLD; không được publish.');document.getElementById('summary').className=s.done?'ready':'blocked'}
document.addEventListener('input',refresh);document.addEventListener('change',refresh);refresh();
function download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.getElementById('pending').onclick=()=>download('public-preview-review.json',new Blob([JSON.stringify(make().p,null,2)],{type:'application/json'}));
document.getElementById('approve').onclick=()=>{const s=make();if(s.done)download('public-preview-approval.json',new Blob([JSON.stringify(s.p,null,2)],{type:'application/json'}))};
document.getElementById('download-provenance').onclick=async()=>{const b=Uint8Array.from(atob(data.provenanceGzip),c=>c.charCodeAt(0));const raw=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();download('provenance-audit.json',new Blob([raw],{type:'application/json'}))};
document.getElementById('download-manifest').onclick=()=>download('export-manifest.json',new Blob([manifestBytes],{type:'application/json'}));
}
start().catch(e=>{document.getElementById('summary').textContent='Không đọc được manifest: '+e.message+'. Giữ PENDING; dùng trình duyệt Chrome/Safari mới để mở tệp.';document.getElementById('approve').disabled=true;});
</script></body></html>'''
